# ## Step 4 — Simulate Two Prompts
#
# Prompt v1 (current): answer directly from the handbook context.
# Prompt v2 (candidate): answer more concisely, avoid unnecessary details.

# %%
async def run_assistant(test_case, prompt_version):
    """Run the policy assistant with real LLM call, using different system prompts."""
    question = test_case["question"]
    context = test_case["context"]
    
    if prompt_version == "v1":
        system = """You are an HR/IT policy assistant. Answer employee questions using only the company handbook context provided.

Context:\n""" + context + "\n\nRules:\n- Provide complete, accurate answers\n- Include relevant details from the handbook\n- If the handbook doesn't address the question, say so\n- Do not make up policies"
    else:  # v2
        system = """You are an HR/IT policy assistant. Answer employee questions using only the company handbook context provided.

Context:\n""" + context + "\n\nRules:\n- Answer concisely, avoid unnecessary details\n- Focus on the most important facts\n- Keep answers brief and to the point\n- Do not make up policies"
    
    messages = [{"role": "user", "content": question}]
    response = await lrn_llm.call(messages, system=system, max_tokens=150)
    return lrn_llm.text(response)

