async def eval_prompt_version(test_cases, version):
    """Run full eval on all test cases for a prompt version."""
    results = []
    for i, tc in enumerate(test_cases):
        print(f"  [{version}] {i+1}/{len(test_cases)}: {tc['id']}...", end=" ")
        # Run assistant
        assistant_answer = await run_assistant(tc, version)
        # Score with LLM judge
        scores = await score_with_llm_judge(
            tc["question"],
            assistant_answer,
            tc["reference"],
            tc["context"]
        )
        result = {
            "test_case_id": tc["id"],
            "question": tc["question"],
            "assistant_answer": assistant_answer,
            "reference_answer": tc["reference"],
            "faithfulness": scores.get("faithfulness", 3),
            "faithfulness_reason": scores.get("faithfulness_reason", ""),
            "completeness": scores.get("completeness", 3),
            "completeness_reason": scores.get("completeness_reason", "")
        }
        results.append(result)
        print(f"✓ (faith={result['faithfulness']}, complete={result['completeness']})")
    return results

